  'Экспорт в PowerPoint': 'Export to PowerPoint',
  'Каждый фрейм станет слайдом. Текст останется текстом, который можно править в PowerPoint и Keynote; фигуры, градиенты, тени и картинки — объектами презентации.': 'Each frame becomes a slide. Text stays text you can edit in PowerPoint and Keynote; shapes, gradients, shadows and images become presentation objects.',
  'Имя файла': 'File name',
  'На странице нет фреймов. Нарисуйте фрейм (F) — он станет слайдом.': 'There are no frames on the page. Draw a frame (F) — it becomes a slide.',
  'Ничего не выделено — экспортируются все фреймы страницы.': 'Nothing is selected — all frames of the page will be exported.',
  'Порядок слайдов — как на холсте: по рядам сверху вниз, в ряду слева направо.': 'Slide order follows the canvas: rows top to bottom, left to right within a row.',
  'У фреймов разный размер: размер слайда берётся по первому, остальные вписываются по центру.': 'Frames differ in size: the slide size comes from the first one, the others are centered to fit.',
