  'Потоки': 'Flows',
  'Поток — это сценарий со своим первым экраном. Выберите фрейм и включите «Начало потока», или просто свяжите экраны: первая связь создаёт поток сама.': 'A flow is a scenario with its own first screen. Select a frame and turn on “Flow starting point”, or just connect screens: the first connection creates a flow.',
