  'Прокручивается то, что выходит за рамку фрейма: сделайте фрейм меньше его содержимого.': 'What extends beyond the frame scrolls: make the frame smaller than its content.',
  'Включите «Обрезать всё, что выходит за рамку» на вкладке «Дизайн», иначе выходящее за рамку будет видно.': 'Turn on “Clip content” on the “Design” tab, otherwise what extends beyond the frame stays visible.',
