  '«Изменить на» работает у вариантов компонента: добавьте взаимодействие варианту (например, «Пока наведено» → «Изменить на» вариант «Наведение»), и все его копии станут интерактивными.': '“Change to” works on component variants: add an interaction to a variant (for example, “While hovering” → “Change to” the “Hover” variant), and all its instances become interactive.',
