  'Копия компонента': 'Instance',
  'Компонент-оригинал удалён. Копия сохраняет последний вид; её можно заменить другим компонентом или отвязать.': 'The main component was deleted. The instance keeps its last look; you can swap it for another component or detach it.',
  'Заменить компонент': 'Swap component',
  'Заменить': 'Swap',
  'Сбросить изменения копии ({0})': 'Reset instance changes ({0})',
  'Отвязать': 'Detach',
  'Отвязать от компонента (⌥⌘B)': 'Detach from component (⌥⌘B)',
  'Изменений нет: копия полностью повторяет компонент.': 'No changes: the instance fully follows the component.',
  'Слой копии компонента': 'Instance layer',
  'Изменено в копии: {0}': 'Changed in the instance: {0}',
  'Слой повторяет компонент. Что вы здесь измените, останется изменением только этой копии.': 'The layer follows the component. What you change here stays a change of this instance only.',
  'Положение, размер и порядок слоёв задаёт компонент.': 'Position, size and layer order are set by the component.',
  'Описание компонента': 'Component description',
  'Копий: {0}. Они повторяют этот компонент: размер, цвета, тексты и слои меняются вместе с ним, кроме того, что изменено в самой копии. На холсте копии обведены фиолетовым пунктиром.': 'Instances: {0}. They follow this component: size, colors, texts and layers change with it, except what was changed in the instance itself. On the canvas instances have a purple dashed outline.',
  'Выделить копии ({0})': 'Select instances ({0})',
  'Копии на других страницах': 'Instances on other pages',
  'Набор вариантов': 'Variant set',
  'Свойство варианта': 'Variant property',
  'Свойство': 'Property',
  'Значения: {0}': 'Values: {0}',
  'Свойство варианта — то, чем варианты отличаются: например «Вид» со значениями «Основная» и «Вторичная» или «Размер» — S, M, L. У копии оно становится выпадающим списком, и вариант переключается без замены слоя.': 'A variant property is what variants differ in: for example “Type” with the values “Primary” and “Secondary”, or “Size” — S, M, L. On an instance it becomes a drop-down, and the variant switches without replacing the layer.',
  'Новое свойство': 'New property',
  'Описание набора': 'Set description',
  'Свойства компонента': 'Component properties',
  'Свойство — настройка, которую можно менять у каждой копии, не отвязывая её от компонента. Три вида: «Текст» (надпись кнопки), «Видимость» (показать иконку или нет), «Замена» (поставить другую вложенную иконку). У копии свойства появляются полями в разделе «Копия компонента».': 'A property is a setting you can change on each instance without detaching it from the component. Three kinds: “Text” (a button label), “Visibility” (show an icon or not), “Swap” (put in another nested icon). On an instance the properties appear as fields in the “Instance” section.',
  'Как добавить: войдите в компонент (двойной щелчок), выделите слой — текст, иконку или вложенную копию компонента — и нажмите кнопку в разделе «Свойство компонента».': 'How to add one: enter the component (double-click), select a layer — text, icon or nested instance — and press the button in the “Component property” section.',
  'Имя свойства': 'Property name',
  'Свойство компонента': 'Component property',
  'удалено': 'deleted',
  'Отвязать от свойства': 'Unbind from property',
  'Сделайте этот слой настраиваемым в копиях: его текст, видимость или (для вложенной копии) замену на другой компонент. Значение по умолчанию — то, что сейчас в компоненте.': 'Make this layer adjustable in instances: its text, visibility or (for a nested instance) swapping for another component. The default value is what the component has now.',
