  'Привязка к родителю': 'Pin to parent',
  'Что делает слой, когда меняют размер фрейма вокруг него: держится левого края, правого, обоих (растягивается), центра или масштабируется.': 'What the layer does when the frame around it is resized: sticks to the left edge, the right, both (stretches), the center, or scales.',
  'Убрать адаптивную раскладку (Shift+A)': 'Remove auto layout (Shift+A)',
  'Добавить адаптивную раскладку (Shift+A)': 'Add auto layout (Shift+A)',
  'Адаптивная раскладка сама расставляет слои внутри фрейма в строку или столбец с одинаковым промежутком, а фрейм подстраивает размер под содержимое — как кнопка, которая растёт вместе с текстом.': 'Auto layout arranges the layers inside a frame in a row or a column with an even gap, and the frame fits its size to the content — like a button that grows with its text.',
  'Включить адаптивную раскладку (Shift+A)': 'Turn on auto layout (Shift+A)',
  'В строку': 'Row',
