  'Распределение': 'Distribution',
  'Точка — куда прижаты слои. Число — расстояние между ними.': 'The dot is where the layers are aligned. The number is the gap between them.',
  'Первый и последний слой прижаты к краям, остальное место делится между слоями поровну.': 'The first and last layers stick to the edges, the rest of the space is shared equally between the layers.',
  'Вокруг каждого слоя одинаковое свободное место.': 'Equal free space around each layer.',
  'Все промежутки, включая края, одинаковые.': 'All gaps, including the edges, are equal.',
