  'Пересечение': 'Intersect',
  'Фигуры внутри остаются редактируемыми: двойной щелчок — войти внутрь. «Слить в одну фигуру» превращает результат в один вектор.': 'The shapes inside stay editable: double-click to enter. “Flatten into one shape” turns the result into a single vector.',
