  'Тяните точки и ручки; щелчок по линии — новая точка; двойной щелчок по точке — угол/сглаживание; Alt — ручки по отдельности; Delete — удалить точку; Esc — выйти.': 'Drag points and handles; click a line to add a point; double-click a point for corner/smooth; Alt — handles separately; Delete — remove a point; Esc — exit.',
