  'Непрозрачность всего слоя вместе с содержимым': 'Opacity of the whole layer with its content',
  'Одинаковое скругление для всех углов': 'Same radius for all corners',
  'Скруглять углы по отдельности': 'Round corners individually',
  'Радиус скругления углов, px. Больше половины меньшей стороны — получится «пилюля» или круг': 'Corner radius, px. More than half the shorter side gives a “pill” or a circle',
  'Радиус скругления углов. Можно тянуть круглые маркеры в углах прямо на холсте': 'Corner radius. You can also drag the round handles in the corners on the canvas',
