  'Как цвета слоя смешиваются со слоями под ним': 'How the layer\'s colors mix with the layers below it',
  'Режим наложения — как цвета слоя смешиваются со слоями под ним (как режимы слоёв в Photoshop). Обычно менять не нужно.': 'Blend mode — how the layer\'s colors mix with the layers below it (like layer modes in Photoshop). Usually there is no need to change it.',
  'Маска показывает слои над собой только внутри своей формы (например, фото в круге). Положите фигуру под картинку и включите — обе окажутся в «Группе с маской».': 'A mask shows the layers above it only inside its shape (for example, a photo in a circle). Put a shape under an image and turn this on — both end up in “Mask group”.',
  'Обрезать всё, что выходит за рамку': 'Clip content',
  'Обрезка': 'Clipping',
  'Показан': 'Visible',
  'Можно привязать к логической переменной': 'Can be bound to a boolean variable',
  'Скрыть слой можно и глазом в списке слоёв. Здесь видимость можно привязать к логической переменной — например, для прототипа.': 'You can also hide a layer with the eye in the layer list. Here visibility can be bound to a boolean variable — for example, for a prototype.',
