  'Показывает текст заглавными или строчными, не меняя сами буквы: удобно для кнопок и заголовков.': 'Shows text in capitals or lowercase without changing the letters themselves: handy for buttons and headings.',
  'Капитель — строчные буквы в виде уменьшенных заглавных. Редкий типографский приём; работает, если он есть в шрифте.': 'Small caps — lowercase letters shaped as smaller capitals. A rare typographic device; works if the font has it.',
  'Кернинг — автоматическая подгонка расстояний между парами букв (например, «AV», «Та»). Обычно его не выключают.': 'Kerning — automatic adjustment of the space between pairs of letters (for example, “AV”, “To”). Usually it stays on.',
