  'Доска для совместной работы': 'A board for working together',
  'Доска для всей команды': 'A board for the whole team',
  'Обсуждения, ретро и схемы — рядом с макетами. Отдельный вид файла в той же Симметрике: те же люди, проекты и доступ, правки видны всем сразу.': 'Discussions, retros and diagrams — next to your designs. A kind of file of its own in the same Simmetrika: the same people, projects and access, everyone sees changes at once.',
  'Доска Симметрики: ретро на стикерах и блок-схема': 'A Simmetrika board: a retro on sticky notes and a flowchart',
  'Попробовать доску': 'Try a board',
  'Без регистрации — доска сохранится в этом браузере': 'No sign-up — the board is kept in this browser',
  'Стикеры': 'Sticky notes',
  'Восемь цветов, шрифт сам подстраивается под текст, под каждым — имя автора. Tab ставит следующий стикер: идеи можно записывать подряд, не трогая мышь.': 'Eight colours, the font adjusts to the text by itself, the author’s name under each. Tab puts the next sticky: write ideas one after another without touching the mouse.',
  'Схемы за минуты': 'Diagrams in minutes',
  'Двенадцать фигур и связи, которые держатся за объекты и идут за ними. Кнопка «+» у фигуры ставит следующий шаг сразу со стрелкой.': 'Twelve shapes and connectors that hold on to objects and follow them. The “+” button of a shape puts the next step with its arrow.',
  'Маркер и штампы': 'Marker and stamps',
  'Обведите главное, подчеркните выделителем, отметьте 👍 и +1 — сразу видно, с чем команда согласна.': 'Circle what matters, underline with the highlighter, mark with 👍 and +1 — you see at once what the team agrees with.',
  'Рядом с макетами': 'Next to the designs',
  'Доска лежит в тех же проектах и открывается тем же людям. Стикеры и схемы копируются в макет и обратно, есть комментарии и история версий.': 'A board lives in the same projects and opens to the same people. Stickies and diagrams copy into a design and back; there are comments and version history.',
  'Настройки инструмента': 'Tool settings',
  'Толщина': 'Width',
  'Размер ластика': 'Eraser size',
  'Как подписывать мои стикеры…': 'How to sign my stickies…',
  'Под стикерами — имя из аккаунта. Сменить: меню аккаунта на главной → «Изменить имя…».': 'Your stickies show your account name. To change it: the account menu on the home screen → “Change name…”.',
  'Как подписывать ваши стикеры?': 'How should your stickies be signed?',
  'Например, Аня': 'For example, Anna',
  'Его увидят под вашими стикерами. Можно оставить пустым и сменить потом: палитра команд → «Как подписывать мои стикеры…».': 'It shows under your stickies. You can leave it empty and change it later: command palette → “How to sign my stickies…”.',
