  'У каждого — несколько голосов: щелчок по стикеру или фигуре ставит голос, Alt+щелчок — убирает. Чужих голосов не видно до конца.': 'Everyone has a few votes: a click on a sticky or a shape votes, Alt+click takes it back. Others’ votes stay hidden until the end.',
