  'Схема': 'Diagram',
  'Схема ещё не построена: поправьте текст слева': 'The diagram is not built yet: fix the text on the left',
  'Схема скопирована. Откройте макет и вставьте её (⌘V) — она станет слоями.': 'The diagram is copied. Open a design and paste it (⌘V) — it becomes layers.',
  'Схема строится по тексту. Выберите тип — появится пример, его можно сразу править.': 'A diagram is built from text. Pick a kind — an example appears, ready to edit.',
  'Таймлайн': 'Timeline',
  'Текст (.txt)': 'Text (.txt)',
  'В файле одна схема. Пока текст не тронут, тип меняется свободно; карты между собой и планы между собой рисуют один и тот же текст.': 'A file holds one diagram. Until its text is touched the kind changes freely; the maps share one text, and so do the plans.',
  'Сменить тип схемы?': 'Change the diagram kind?',
  'Текст написан для типа «{0}», а у типа «{1}» другая запись. Текст заменится примером — вернуть прежний можно через ⌘Z или историю версий.': 'The text is written for “{0}”, and “{1}” is written differently. The text will be replaced with an example — ⌘Z or the version history brings it back.',
  'Открыть «{0}» в новом файле': 'Open “{0}” in a new file',
  'Текст схемы': 'Diagram text',
  'Текст схемы заменится примером этого типа. Вернуть прежний — ⌘Z.': 'The diagram’s text will be replaced with an example of this kind. ⌘Z brings it back.',
