  'Новое имя': 'New name',
  '$& — прежнее имя, $n — номер (1, 2, 3), $nn — с нулём (01, 02), $N — номер в обратном порядке. Номера идут сверху вниз, как в панели слоёв.': '$& — the old name, $n — a number (1, 2, 3), $nn — with a zero (01, 02), $N — counting down. Numbers go top down, as in the layers panel.',
