  'Стандарт': 'Standard',
  'По буквам': 'Cap height',
  '«По буквам» — блок от верха заглавных до базовой линии последней строки, без пустоты сверху и снизу: отступы в кнопках и адаптивной раскладке становятся такими, как видно глазу.': '“Cap height” — the box runs from the top of the capitals to the last line’s baseline, no empty room above or below: padding in buttons and auto layout becomes what the eye sees.',
  'Функции шрифта': 'Font features',
  'Функции и оси шрифта (цифры одной ширины, наборы знаков, дроби) видны, когда файл шрифта есть в файле: выбор шрифта → «Встроить в файл». Шрифты WOFF2 прочитать нельзя — встройте TTF или OTF.': 'Font features and axes (digits of one width, stylistic sets, fractions) show when the font’s file is in the file: font picker → “Embed in the file”. WOFF2 fonts cannot be read — embed a TTF or OTF.',
  'Наборы знаков': 'Stylistic sets',
  'Варианты знаков': 'Character variants',
  'То, что умеет сам шрифт: цифры одной ширины для таблиц и цен, дроби, другие формы букв. Показано только то, что есть в этом шрифте.': 'What the font itself can do: digits of one width for tables and prices, fractions, other letter forms. Only what this font has is shown.',
  'Оси шрифта': 'Font axes',
  'Толщина: любое число от {0} до {1}': 'Weight: any number from {0} to {1}',
  '{0}: от {1} до {2}': '{0}: from {1} to {2}',
  'Ось шрифта': 'Font axis',
  'Вариативный шрифт плавно меняется по своим осям: толщина — любым числом (например 450), а не только 400 или 500.': 'A variable font changes smoothly along its axes: the weight takes any number (450, say), not just 400 or 500.',
  'Текст в кривых': 'Text as outlines',
  'Буквы становятся контурами: SVG выглядит одинаково везде, даже без шрифта. Нужен файл шрифта — встроенный в файл или Inter': 'Letters become paths: the SVG looks the same everywhere, even without the font. Needs the font’s file — embedded in the file, or Inter',
  'Текст шрифтом «{0}» оставлен текстом: этого шрифта нет в файле. Встройте его (выбор шрифта → «Встроить в файл»), чтобы он ушёл в кривых': 'Text in “{0}” stayed text: this font is not in the file. Embed it (font picker → “Embed in the file”) to export it as outlines',
