  'Линия меняет толщину вдоль пути или рисуется кистью, как от руки. Пунктир и обводка внутри/снаружи тогда не действуют.': 'The line changes its width along the path or is drawn with a brush, as by hand. Dashes and inside/outside strokes do not apply then.',
