  'Ровный': 'Balanced',
  'Без висячих': 'No orphans',
  '«Ровный» — строки абзаца примерно одной длины (для заголовков). «Без висячих» — последнее слово не остаётся на строке одно. Рамка текста не меняется.': '“Balanced” — a paragraph’s lines of about equal length (for headings). “No orphans” — the last word never stands alone on its line. The text box stays as it is.',
  'Маркеры за краем текста': 'Markers outside the text edge',
  'Висячий список': 'Hanging list',
  'Маркеры и номера выходят за левый край, а текст пунктов стоит ровно по краю — вровень с текстом вокруг.': 'Bullets and numbers stand past the left edge; the items’ text lines up with the text around.',
  'Висячие кавычки и скобки': 'Hanging quotes and brackets',
  'Висячая пунктуация': 'Hanging punctuation',
  'Кавычка или скобка в начале строки выходит за край, и буквы стоят ровно по краю. У текста по правому краю так же выходят точка, запятая и закрывающая кавычка.': 'A quote or bracket at a line’s start stands past the edge, so the letters line up. In right-aligned text the full stop, comma and closing quote do the same.',
