  'Убрать все мазки': 'Clear all strokes',
  'Затемнено то, что уйдёт. Не так — проведите кистью: «Оставить» по пропавшей части предмета, «Убрать» по оставшемуся фону. Alt — другая кисть.': 'What goes is dimmed. If it is wrong, brush over it: “Keep” over a part of the object that went, “Remove” over background that stayed. Alt — the other brush.',
  'Вырезаю…': 'Cutting out…',
  'Ничего не осталось: отметьте кистью «Оставить» сам предмет.': 'Nothing is left: mark the object itself with the “Keep” brush.',
  'Готовлю картинку…': 'Preparing the picture…',
  'Однотонный фон уходит сразу; у фото — окно, где можно поправить вырезку кистями «Оставить» и «Убрать». Картинка никуда не загружается.': 'A plain background goes at once; for a photo a window opens where the cut can be corrected with the “Keep” and “Remove” brushes. The picture is not uploaded anywhere.',
  'Однотонный фон уходит сразу, у фото — вырезка с правкой кистями; картинка никуда не загружается': 'A plain background goes at once, a photo is cut out and can be corrected with brushes; the picture is not uploaded anywhere',
  'Не получилось отделить предмет от фона: попробуйте картинку, где предмет крупнее и не касается краёв.': 'Could not separate the object from the background: try a picture where the object is larger and does not touch the edges.',
