  'картинки в формате WMF и HD Photo': 'WMF and HD Photo pictures',
  'Масштаб — вместе с текстом и обводками': 'Scale — with text and strokes',
  'Масштаб (K): выделите слой и тяните за угол рамки — он увеличится целиком, вместе с размером текста, толщиной обводок, скруглениями и тенями. Обычное растягивание меняет только ширину и высоту. Esc или V — обычное перемещение.': 'Scale (K): select a layer and drag a corner of its box — it grows as a whole, with its text size, stroke widths, corner radii and shadows. Ordinary resizing changes only width and height. Esc or V — back to Move.',
  'Масштаб (K): тяните за угол рамки — слой увеличится целиком: размер текста, толщина обводок, скругления и тени меняются вместе с ним. Точное «во сколько раз» — справа, в разделе «Масштаб». Esc или V — обычное перемещение.': 'Scale (K): drag a corner of the box — the layer grows as a whole: text size, stroke widths, corner radii and shadows change with it. An exact factor — on the right, in the Scale section. Esc or V — back to Move.',
