  'Опишите слайд словами: нейросеть сверстает его точно в размер слайдов презентации — {0} × {1}, и он станет редактируемыми слоями.': 'Describe the slide in words: the model lays it out in the exact size of the presentation’s slides — {0} × {1}, and it becomes editable layers.',
