  'Высота рамки — по содержимому: свободного места нет, по вертикали выравнивать и распределять нечего.': 'The frame hugs its content in height: no room left, nothing to align or distribute vertically.',
  'Слой заполняет всё свободное место по ширине — распределять нечего.': 'A layer fills all the room left in width — nothing to distribute.',
  'Слой заполняет всё свободное место по высоте — распределять нечего.': 'A layer fills all the room left in height — nothing to distribute.',
