  'В презентацию попадёт слайд со страницы — то, что в превью, без фона вокруг; он станет новым слайдом в формате презентации.': 'The page’s slide goes into the presentation — what the preview shows, without what is around it; it becomes a new slide in the presentation’s format.',
  'Страница станет новым слайдом: она впишется в формат презентации целиком.': 'The page becomes a new slide: it is fitted whole into the presentation’s format.',
  'Лендинг кофейни: шапка с меню, большой первый экран, три карточки напитков, отзывы, подвал': 'Coffee shop landing page: header with a menu, a big hero, three drink cards, reviews, a footer',
  'Экран входа в мобильный банк: логотип, телефон, код из СМС, кнопка «Войти»': 'Mobile bank sign-in screen: logo, phone number, SMS code, a “Sign in” button',
  'Дашборд продаж: боковое меню, четыре карточки с цифрами, график по месяцам, таблица последних заказов': 'Sales dashboard: side menu, four number cards, a monthly chart, a table of recent orders',
  'Опишите экран: что на нём, для кого, в каком стиле': 'Describe the screen: what is on it, who it is for, what style',
