  'Маршрут собирали в таблицах, бронировали по телефону.': 'Routes were planned in spreadsheets, booked by phone.',
  'Маршрут и бронь — в одном приложении за пару минут.': 'Route and booking in one app in a couple of minutes.',
  'Что поменялось для путешественника.': 'What changed for the traveller.',
  'Наконец-то поездка собирается за вечер, а не за неделю.': 'Finally a trip comes together in an evening, not a week.',
  '— Анна, путешествует из Казани': '— Anna, travels from Kazan',
  'Отзыв из магазина приложений — читаем вслух.': 'A review from the app store — read it aloud.',
  'Скажите словами, что поправить: нейросеть изменит макет, а вы сравните до и после. Правку можно продолжать, пока не понравится.': 'Say what to change: the AI changes the layout and you compare before and after. Keep refining until you like it.',
  'Опишите экран словами: нейросеть сверстает его, и он станет редактируемыми слоями.': 'Describe the screen in words: the AI lays it out and it becomes editable layers.',
  'Слайд изменится на месте: его слои заменятся тем, что в превью, а заметки, место в презентации и тема останутся.': 'The slide changes in place: its layers become what the preview shows; notes, its place in the deck and the theme stay.',
