  'Макет по тексту': 'Layout from text',
  'Макет по описанию: нейросеть сверстает экран': 'Layout from a description: the model lays out a screen',
  'Опишите словами': 'Describe in words',
  'Что на экране, для кого и в каком стиле. Подойдут и короткое «лендинг кофейни», и подробное ТЗ.': 'What is on the screen, who it is for, what style. A short “coffee shop landing” will do, and so will a detailed brief.',
  'Доработайте текстом': 'Refine in words',
  '«Шапку тёмной, добавь четвёртую карточку» — правка ляжет на тот же макет, прежний вариант можно вернуть.': '“Make the header dark, add a fourth card” — the change goes onto the same layout, the previous version can be brought back.',
  'Данные из файлов': 'Data from files',
  'Прикрепите таблицу Excel, CSV или документ Word — в макете будут ваши цены, имена и цифры.': 'Attach an Excel sheet, a CSV or a Word document — the layout gets your prices, names and numbers.',
  'Сразу слои': 'Layers right away',
  'Не картинка: фреймы, тексты и иконки на адаптивной раскладке. Дальше — как с любым макетом.': 'Not a picture: frames, texts and icons on auto layout. From there — as with any layout.',
  'Лендинг кофейни: шапка с меню, большой первый экран, три карточки напитков с ценами из файла': 'Coffee shop landing: header with a menu, a big hero, three drink cards with prices from the file',
  'Сделай кнопки круглыми': 'Make the buttons round',
  'Кофе, ради которого просыпаются': 'Coffee worth waking up for',
  'Заказать': 'Order',
  'Раф лавандовый': 'Lavender raf',
  'Флэт уайт': 'Flat white',
  'Опишите экран — получите макет': 'Describe a screen — get a layout',
  'Напишите, какой экран нужен, — нейросеть сверстает его за минуту, и он сразу станет редактируемыми слоями. Не понравилось — скажите, что поправить, словами. Это есть и для готовых макетов: выделите фрейм и нажмите ✦.': 'Write what screen you need — the model lays it out in a minute, and it becomes editable layers right away. Not quite right — say what to change, in words. Works for existing layouts too: select a frame and press ✦.',
  'Нужен аккаунт: макет создаёт нейросеть на сервере. До 20 макетов в сутки.': 'An account is needed: the model makes the layout on the server. Up to 20 layouts a day.',
  'Умные действия — без ожидания': 'Smart actions — no waiting',
  'Привести в порядок, заполнить данными, исправить контраст, палитра из картинки, тёмная тема. Кнопка ✦ предлагает только то, что подходит к выделенному, и заранее пишет, что сделает. Всё это считается на вашем компьютере, мгновенно и без нейросети.': 'Tidy up, fill with data, fix contrast, a palette from a picture, a dark theme. The ✦ button offers only what fits the selection and says beforehand what it will do. All of it is computed on your computer, instantly and without a model.',
  'Нейросеть не поняла, что поменять. Скажите иначе — например, какой текст или блок и на что.': 'The model did not get what to change. Say it differently — e.g. which text or block and into what.',
  'Сделана часть правки: {0} из {1} мест нейросеть не нашла. Проверьте превью или скажите точнее.': 'Part of the change is made: the model did not find {0} of {1} places. Check the preview or say it more precisely.',
