  'Привести в порядок — мгновенно, на вашем компьютере. Переименовать слои по смыслу, придумать тексты для макета и заметки к слайду — за пару секунд, с нейросетью. Кнопка ✦ предлагает только то, что подходит к выделенному, и заранее пишет, что сделает.': 'Tidy up — instantly, on your computer. Layer names by meaning, texts for a layout and notes for a slide — in a couple of seconds, with the model. The ✦ button offers only what fits the selection and says beforehand what it will do.',
